ography","sources":["http://data.bibliotheken.nl/id/nbt/p447675451"],"reference":"work:1399","checked_at":"2026-11-03T09:19:36.616Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-015.json","sources":["https://openlibrary.org/works/OL45586866W","https://data.bibliotheken.nl/id/nbt/p447675451"]},{"note":"Source-bound bulk attempt yielded no verified importedasset. Preserve existing resolver and require actualfrontor documentedneutralplaceholder hosted. This is neitherbookabsence nor a repairedcover.","type":"no_verified_cover_asset_retained","isbn13":"9789044369267","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15225998,"receipt":"cover-archive-v2-readback.json","receiptSha256":"da70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-03T09:19:36.616Z","editionKey":"/books/OL62083371M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"cover_url":null,"edition_id":987245004,"bound_title":"Adem","reviewed_at":"2026-11-03T09:19:36.616+00:00","bound_isbn13":"9789044369267","evidence_url":"https://data.bibliotheken.nl/id/nbt/p447675451","review_batch":"nl-scale-20261102-046","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":936300659}'::jsonb as exact union all select 'catalog_work_descriptions:9' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987145005 and t.language='nl')='{"text":"Dai Carter beschrijft welke lessen hij meeneemt uit zijn loopbaan bij de Nederlandse Special Forces. Daarbij richt hij zich vooral op mentale kracht en op de manier waarop mensen onder druk reageren. Hij verbindt ervaringen uit een veeleisende militaire omgeving met vragen uit het dagelijks leven. Het boek nodigt uit om over eigen handelen en doorzettingsvermogen na te denken. Carters persoonlijke benadering staat centraal; zijn ervaringen vormen geen garantie dat iedere lezer dezelfde verandering zal doormaken.","work_id":987145005,"evidence":[{"note":"NuOfNooit/DaiCarter9789044648560 exactDutchPaperback, militarylife lessons/personalresilience, no universalhealthclaimsorautomaticfiction/tastefeatures.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p433338601"],"reference":"work:1545","checked_at":"2026-11-03T09:19:36.616Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-015.json","sources":["https://uitgeverijprometheus.nl/boeken/nu-of-nooit-paperback/","https://openlibrary.org/works/OL37232624W","https://data.bibliotheken.nl/id/nbt/p433338601"]},{"note":"Source-bound bulk attempt yielded no verified importedasset. Preserve existing resolver and require actualfrontor documentedneutralplaceholder hosted. This is neitherbookabsence nor a repairedcover.","type":"no_verified_cover_asset_retained","isbn13":"9789044648560","status":"no_verified_asset_retained","attempts":[{"status":"bulk_source_failure_no_retry","coverId":14549549,"receipt":"cover-archive-v2-readback.json","receiptSha256":"da70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-03T09:19:36.616Z","editionKey":"/books/OL50194143M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://uitgeverijprometheus.nl/boeken/nu-of-nooit-paperback/","reviewed_at":"2026-11-03T09:19:36.616+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-046","review_status":"approved","bound_author_id":987345005}'::jsonb as exact union all select 'catalog_edition_metadata:10' as ref,(select to_jsonb(t) from public.catalog_edition_metadata t w