ok de spanning tussen muzikale ambities en persoonlijke verhoudingen. De roman kijkt terug op de opkomst van deze fictieve rockgroep in de jaren zeventig en op de breuk die daarop volgde.","work_id":987145016,"evidence":[{"note":"DaisyJonesAndTheSix2019 exact9789026361333 DutchPaperbackdespiteEnglishretainedtitle. Fictional rockband novel, not realbandbiography.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p436063190"],"reference":"work:3266","checked_at":"2026-11-03T09:19:36.616Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-021.json","sources":["https://openlibrary.org/works/OL19922194W","https://data.bibliotheken.nl/id/nbt/p436063190"]},{"note":"Source-bound bulk attempt yielded no verified importedasset. Preserve existing resolver and require actualfrontor documentedneutralplaceholder hosted. This is neitherbookabsence nor a repairedcover.","type":"no_verified_cover_asset_retained","isbn13":"9789026361333","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15138977,"receipt":"cover-archive-v2-readback.json","receiptSha256":"da70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-03T09:19:36.616Z","editionKey":"/books/OL60586027M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL19922194W","reviewed_at":"2026-11-03T09:19:36.616+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-046","review_status":"approved","bound_author_id":978300030}'::jsonb as exact union all select 'catalog_edition_metadata:24' as ref,(select to_jsonb(t) from public.catalog_edition_metadata t where t.edition_id=987245021)='{"format":"