t ondertussen hulp nodig bij zijn studie om zijn sportplannen niet te verliezen. Ze spreken af dat Hannah hem bijles geeft en hij met haar op een zogenaamd afspraakje gaat. De ruil lijkt hun afzonderlijke problemen op te lossen. Naarmate zij elkaar beter leren kennen, blijkt het alleen lastiger om hun contact als een praktische overeenkomst te blijven behandelen.","work_id":987145002,"evidence":[{"note":"TheDeal2015 firstOffCampusnovel=DeDeal9789021409085DutchPaperback, Hannah/Garrett; not any unrelatedsame-titledbusinessbook.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p413679942"],"reference":"work:1362","checked_at":"2026-11-03T09:19:36.616Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-021.json","sources":["https://openlibrary.org/works/OL42430111W","https://data.bibliotheken.nl/id/nbt/p413679942"]},{"note":"Source-bound bulk attempt yielded no verified importedasset. Preserve existing resolver and require actualfrontor documentedneutralplaceholder hosted. This is neitherbookabsence nor a repairedcover.","type":"no_verified_cover_asset_retained","isbn13":"9789021409085","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15176847,"receipt":"cover-archive-v2-readback.json","receiptSha256":"da70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-03T09:19:36.616Z","editionKey":"/books/OL61375848M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL42430111W","reviewed_at":"2026-11-03T09:19:36.616+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-046","review_status":"approved","bound_author_id":987345003}'::js