ip van New York naar Buenos Aires wordt de wereldkampioen schaken uitgedaagd door medepassagiers. Een Oostenrijkse emigrant grijpt adviserend in en blijkt een opmerkelijk inzicht in het spel te hebben. Achter die kennis ligt een geschiedenis van gevangenschap en afzondering door de Gestapo. Een nieuwe partij krijgt daardoor voor hem een betekenis die verder gaat dan winnen of verliezen. Stefan Zweig verbindt de spanning aan het schaakbord met de gevolgen van een extreme geestelijke beproeving.","work_id":987145004,"evidence":[{"note":"StandaloneSchachnovelle=Schaaknovelle9789061331087DutchHardcover. StorysourceboundZweigship/Gestapoconfinement; existingWorkyearnot silentlychanged from mixedtranslationeditions.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p803110456"],"reference":"work:1472","checked_at":"2026-11-03T09:19:36.616Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-021.json","sources":["https://openlibrary.org/works/OL28429W","https://data.bibliotheken.nl/id/nbt/p803110456"]},{"note":"Source-bound bulk attempt yielded no verified importedasset. Preserve existing resolver and require actualfrontor documentedneutralplaceholder hosted. This is neitherbookabsence nor a repairedcover.","type":"no_verified_cover_asset_retained","isbn13":"9789061331087","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":7069382,"receipt":"cover-archive-v2-readback.json","receiptSha256":"da70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-03T09:19:36.616Z","editionKey":"/books/OL25208728M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL28429W","reviewed_at":"2026-11-03T09:19:36.616+00:00","source_n