-scale-20261102-046","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987345001}'::jsonb as exact union all select 'catalog_work_descriptions:31' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987145020 and t.language='nl')='{"text":"Wanneer Sam Masur en Sadie Green elkaar als studenten opnieuw ontmoeten, herleeft hun band uit de kindertijd. Ze besluiten samen een computerspel te maken. Het succes daarvan opent mogelijkheden die zij nog nauwelijks kunnen overzien, maar neemt de spanning tussen hun verschillende ambities niet weg. Over een periode van tientallen jaren volgt de roman hun samenwerking, conflicten en behoefte aan verbondenheid. Het maken van spellen vormt daarbij zowel hun gezamenlijke taal als een bron van vragen over wie zij voor elkaar zijn.","work_id":987145020,"evidence":[{"note":"TomorrowAndTomorrowAndTomorrow2022=MorgenEnMorgenEnMorgen9789046829202DutchPaperback. Sam/Sadiegamedevelopmentnovel, notShakespeareplaycitedintitle.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p436338572"],"reference":"work:3291","checked_at":"2026-11-03T09:19:36.616Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-021.json","sources":["https://openlibrary.org/works/OL26004554W","https://data.bibliotheken.nl/id/nbt/p436338572"]},{"note":"Source-bound bulk attempt yielded no verified importedasset. Preserve existing resolver and require actualfrontor documentedneutralplaceholder hosted. This is neitherbookabsence nor a repairedcover.","type":"no_verified_cover_asset_retained","isbn13":"9789046829202","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15142577,"receipt":"cover-archive-v2-readback.json","receiptSha256":"da70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-03T09:19:36.616Z","editionKey":"/books/OL606